1	export interface Item {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	}
7	
8	export interface QuoteStep {
9	  op: "quote";
10	  items: Item[];
11	}
12	
13	export interface Damage {
14	  itemType: string;
15	  amount: number;
16	}
17	
18	export interface ClaimStep {
19	  op: "claim";
20	  policy: number;
21	  incident: { cause: string; damages: Damage[] };
22	}
23	
24	export type Step = QuoteStep | ClaimStep;
25	
26	export interface Customer {
27	  yearsWithMHPCO: number;
28	}
29	
30	export interface Scenario {
31	  customer: Customer;
32	  steps: Step[];
33	}
34	
35	export interface QuoteResult {
36	  premium: number;
37	}
38	
39	export interface ClaimResult {
40	  payout: number;
41	  remainingCap: number;
42	}
43	
44	export interface ScenarioResults {
45	  results: (QuoteResult | ClaimResult)[];
46	}
47	
48	const sumBy = <T>(items: T[], amountOf: (item: T) => number): number =>
49	  items.reduce((total, item) => total + amountOf(item), 0);
50	
51	const PROCESSING_FEE = 5;
52	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
53	
54	const BASE_PREMIUMS = {
55	  sword: 100,
56	  amulet: 60,
57	  staff: 80,
58	  potion: 40,
59	  rune: 25,
60	  moonstone: 25,
61	} as const satisfies Record<string, number>;
62	
63	export type InsurableItemType = keyof typeof BASE_PREMIUMS;
64	
65	const basePremiumForType = (type: string): number =>
66	  BASE_PREMIUMS[type as InsurableItemType];
67	
68	const BLOCK_SIZE = 3;
69	const BLOCK_PREMIUM = 60;
70	
71	// Items of one type, quoted together. A group of exactly 3 forms a building
72	// block and is offered at a flat base premium; any other size is priced per
73	// item. "Alike" means the same item type — 2 runes + 1 moonstone is two
74	// groups, so neither is a block.
75	type AlikeGroup = [type: string, items: Item[]];
76	
77	const intoAlikeGroups = (items: Item[]): AlikeGroup[] => {
78	  const groups = new Map<string, Item[]>();
79	  for (const item of items) {
80	    groups.set(item.type, [...(groups.get(item.type) ?? []), item]);
81	  }
82	  return [...groups];
83	};
84	
85	const isBuildingBlock = ([, items]: AlikeGroup): boolean =>
86	  items.length === BLOCK_SIZE;
87	
88	const basePremiumForGroup = (group: AlikeGroup): number => {
89	  const [type, items] = group;
90	  return isBuildingBlock(group)
91	    ? BLOCK_PREMIUM
92	    : items.length * basePremiumForType(type);
93	};
94	
95	const sumBasePremiums = (items: Item[]): number =>
96	  sumBy(intoAlikeGroups(items), basePremiumForGroup);
97	
98	const CURSE_SURCHARGE_RATE = 0.5;
99	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
100	const HIGH_ENCHANTMENT_THRESHOLD = 5;
101	
102	const isHighlyEnchanted = (item: Item): boolean =>
103	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
104	
105	// Item-specific modifiers apply to the base premium of the affected item, not
106	// to the policy total.
107	const surchargeRateForItem = (item: Item): number =>
108	  (item.cursed ? CURSE_SURCHARGE_RATE : 0) +
109	  (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE_RATE : 0);
110	
111	// Surcharges are charged against the item's own base premium, ignoring any
112	// building-block discount the item may be part of.
113	const surchargeForItem = (item: Item): number =>
114	  basePremiumForType(item.type) * surchargeRateForItem(item);
115	
116	const sumItemSurcharges = (items: Item[]): number =>
117	  sumBy(items, surchargeForItem);
118	
119	// Every amount is rounded in the MHPCO's favour, which cuts in opposite
120	// directions on either side of the ledger: a premium owed to the office rounds
121	// up, a payout owed by it rounds down. Only the final figure is rounded;
122	// intermediate amounts stay fractional.
123	const roundPremiumInMHPCOsFavour = Math.ceil;
124	const roundPayoutInMHPCOsFavour = Math.floor;
125	
126	const LOYALTY_DISCOUNT_RATE = 0.2;
127	const LOYALTY_YEARS_THRESHOLD = 2;
128	
129	const isLoyal = (customer: Customer): boolean =>
130	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
131	
132	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
133	
134	// Policy-wide modifiers are summed into one net rate, not compounded. The net
135	// is signed: a loyal customer's discount can outweigh the surcharge.
136	//
137	// The first insurance surcharge applies to every quote — each item in a quote
138	// is treated as a first insurance, regardless of customer history — so it is
139	// not cancelled by the follow-up contract discount.
140	const policyModifierRateFor = (
141	  customer: Customer,
142	  precedingContracts: number,
143	): number =>
144	  FIRST_INSURANCE_SURCHARGE_RATE -
145	  (isLoyal(customer) ? LOYALTY_DISCOUNT_RATE : 0) -
146	  (precedingContracts > 0 ? FOLLOW_UP_CONTRACT_DISCOUNT_RATE : 0);
147	
148	// Charged against the policy base premium — the sum of all item base premiums —
149	// and added to it, mirroring how surchargeForItem works per item.
150	const policyModifierFor = (
151	  basePremium: number,
152	  customer: Customer,
153	  precedingContracts: number,
154	): number => basePremium * policyModifierRateFor(customer, precedingContracts);
155	
156	const quotePremium = (
157	  items: Item[],
158	  customer: Customer,
159	  precedingContracts: number,
160	): number => {
161	  const basePremium = sumBasePremiums(items);
162	  const itemSurcharges = sumItemSurcharges(items);
163	  const policyModifier = policyModifierFor(
164	    basePremium,
165	    customer,
166	    precedingContracts,
167	  );
168	  return roundPremiumInMHPCOsFavour(
169	    basePremium + itemSurcharges + policyModifier + PROCESSING_FEE,
170	  );
171	};
172	
173	// An item's insured worth, distinct from what it costs to insure.
174	const INSURANCE_VALUES = {
175	  sword: 1000,
176	  amulet: 600,
177	  staff: 800,
178	  potion: 400,
179	  rune: 250,
180	  moonstone: 250,
181	} as const satisfies Record<InsurableItemType, number>;
182	
183	const insuranceValueForType = (type: string): number =>
184	  INSURANCE_VALUES[type as InsurableItemType];
185	
186	const DEDUCTIBLE = 100;
187	const CAP_MULTIPLE = 2;
188	
189	// A quote step creates a policy; later claim steps refer to it by that step's
190	// index. The cap is consumed as claims are paid.
191	interface Policy {
192	  items: Item[];
193	  remainingCap: number;
194	}
195	
196	// The policy's total insured worth.
197	const insuranceSumFor = (items: Item[]): number =>
198	  sumBy(items, (item) => insuranceValueForType(item.type));
199	
200	// The most the policy will ever pay out, derived from the plain item values.
201	// Nothing that moves the premium moves the cap: item surcharges cannot inflate
202	// it, and the building-block discount cannot deflate it.
203	const capFor = (items: Item[]): number =>
204	  CAP_MULTIPLE * insuranceSumFor(items);
205	
206	// The policy owns its item list: it is copied out of the step so that draining
207	// a claim's pool can never reach back into the caller's scenario.
208	const openPolicy = (items: Item[]): Policy => ({
209	  items: [...items],
210	  remainingCap: capFor(items),
211	});
212	
213	// Claims use their own, higher enchantment threshold — unrelated to the
214	// premium-side high-enchantment surcharge.
215	const REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;
216	const HEAVY_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;
217	const FULL_REIMBURSEMENT_RATE = 1;
218	
219	const isHeavilyEnchanted = (item: Item): boolean =>
220	  (item.enchantment ?? 0) >= REIMBURSEMENT_ENCHANTMENT_THRESHOLD;
221	
222	// Damage to a heavily enchanted item is only half reimbursed.
223	//
224	// The spec's dragon-material clause is deliberately absent, not forgotten: it
225	// grants full reimbursement, which is already the default, and the heavy
226	// enchantment rule overrides it where both apply. No input exists for which
227	// reading `material` would change the payout, so a branch on it would be dead
228	// code. Reinstate one only if a rule makes dragon material differ from the
229	// default.
230	const reimbursementRateFor = (item: Item): number =>
231	  isHeavilyEnchanted(item)
232	    ? HEAVY_ENCHANTMENT_REIMBURSEMENT_RATE
233	    : FULL_REIMBURSEMENT_RATE;
234	
235	// Each damage entry is charged against one insured item, which no later entry
236	// may reuse — two sword damages need two insured swords. `unclaimed` is drained
237	// as entries are matched.
238	const claimInsuredItem = (unclaimed: Item[], damage: Damage): Item => {
239	  const at = unclaimed.findIndex((item) => item.type === damage.itemType);
240	  if (at === -1) {
241	    throw new Error(
242	      `the policy does not cover a ${damage.itemType} for this damage`,
243	    );
244	  }
245	  return unclaimed.splice(at, 1)[0];
246	};
247	
248	// The reimbursement rate applies to the damage first; the deductible comes off
249	// what remains, once per damage event rather than once per claim.
250	const payoutForDamage = (item: Item, damage: Damage): number =>
251	  damage.amount * reimbursementRateFor(item) - DEDUCTIBLE;
252	
253	// Settling a claim consumes the policy's cap, so the policy carries less cover
254	// into the next claim. Kept separate from settleClaim so the state change is
255	// visible where the policy is held rather than hidden behind a pure-looking call.
256	const consumeCap = (policy: Policy, result: ClaimResult): Policy => ({
257	  ...policy,
258	  remainingCap: result.remainingCap,
259	});
260	
261	const settleClaim = (policy: Policy, damages: Damage[]): ClaimResult => {
262	  const unclaimed = [...policy.items];
263	  // Per-damage amounts stay fractional; the claim total is rounded once.
264	  const desired = roundPayoutInMHPCOsFavour(
265	    sumBy(damages, (damage) =>
266	      payoutForDamage(claimInsuredItem(unclaimed, damage), damage),
267	    ),
268	  );
269	  // The cap limits what the policy will pay, so a claim beyond it is paid out
270	  // only as far as the cap reaches.
271	  const payout = Math.min(desired, policy.remainingCap);
272	  return { payout, remainingCap: policy.remainingCap - payout };
273	};
274	
275	const runStep = (
276	  step: Step,
277	  customer: Customer,
278	  precedingContracts: number,
279	  policies: Map<number, Policy>,
280	  stepIndex: number,
281	): QuoteResult | ClaimResult => {
282	  switch (step.op) {
283	    case "quote":
284	      policies.set(stepIndex, openPolicy(step.items));
285	      return { premium: quotePremium(step.items, customer, precedingContracts) };
286	    case "claim": {
287	      const policy = policies.get(step.policy)!;
288	      const result = settleClaim(policy, step.incident.damages);
289	      policies.set(step.policy, consumeCap(policy, result));
290	      return result;
291	    }
292	  }
293	};
294	
295	// Each quote in a scenario forms a contract, so every quote after the first is
296	// a follow-up. Steps are run in order and a step sees only the contracts that
297	// precede it. Only quote steps create contracts.
298	export const runScenario = (scenario: Scenario): ScenarioResults => {
299	  const results: (QuoteResult | ClaimResult)[] = [];
300	  const policies = new Map<number, Policy>();
301	  let contractsSoFar = 0;
302	  scenario.steps.forEach((step, stepIndex) => {
303	    results.push(
304	      runStep(step, scenario.customer, contractsSoFar, policies, stepIndex),
305	    );
306	    if (step.op === "quote") contractsSoFar += 1;
307	  });
308	  return { results };
309	};
